Here is the commit message:
ravb: avoid unused function warnings

When CONFIG_PM_SLEEP is disabled, we get a couple of harmless warnings:

drivers/net/ethernet/renesas/ravb_main.c:2117:12: error: 'ravb_resume' defined but not used [-Werror=unused-function]
drivers/net/ethernet/renesas/ravb_main.c:2104:12: error: 'ravb_suspend' defined but not used [-Werror=unused-function]

The simplest solution here is to replace the #ifdef with __maybe_unused
annotations, which lets the compiler do the right thing by itself.

Signed-off-by: Arnd Bergmann <arnd@arndb.de>
Fixes: 0184165b2f42 ("ravb: add sleep PM suspend/resume support")
Acked-by: Sergei Shtylyov <sergei.shtylyov@cogentembedded.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The root cause of the bug is the presence of unused function warnings generated by the compiler when the `CONFIG_PM_SLEEP` configuration option is disabled. The functions `ravb_suspend` and `ravb_resume` were defined but not used in this configuration, leading to warnings that were treated as errors due to the `-Werror` flag. This situation arose because the code was conditionally compiled based on the power management configuration, which resulted in these functions being defined but not utilized when power management was disabled.

Here is the patch:

-#ifdef CONFIG_PM
-static int ravb_suspend(struct device *dev)
+static int __maybe_unused ravb_suspend(struct device *dev)
 {
 	struct net_device *ndev = dev_get_drvdata(dev);
 	int ret = 0;

 	if (netif_running(ndev)) {
 		netif_device_detach(ndev);
 		ret = ravb_close(ndev);
 	}

 	return ret;
 }

-static int ravb_resume(struct device *dev)
+static int __maybe_unused ravb_resume(struct device *dev)
 {
 	struct net_device *ndev = dev_get_drvdata(dev);
 	struct ravb_private *priv = netdev_priv(ndev);
 	int ret = 0;

 	/* All register have been reset to default values.
 	 * Restore all registers which where setup at probe time and
 	 * reopen device if it was running before system suspended.
 	 */

 	/* Set AVB config mode */
 	ravb_set_config_mode(ndev);

 	/* Set GTI value */
 	ret = ravb_set_gti(ndev);
 	if (ret)
 		return ret;

 	/* Request GTI loading */
 	ravb_modify(ndev, GCCR, GCCR_LTI, GCCR_LTI);

 	/* Restore descriptor base address table */
 	ravb_write(ndev, priv->desc_bat_dma, DBAT);

 	if (netif_running(ndev)) {
 		ret = ravb_open(ndev);
 		if (ret < 0)
 			return ret;
 		netif_device_attach(ndev);
 	}

 	return ret;
 }

-static int ravb_runtime_nop(struct device *dev)
+static int __maybe_unused ravb_runtime_nop(struct device *dev)
 {
 	/* Runtime PM callback shared between ->runtime_suspend()
 	 * and ->runtime_resume(). Simply returns success.
 	 *
 	 * This driver re-initializes all registers after
 	 * pm_runtime_get_sync() anyway so there is no need
 	 * to save and restore registers here.
 	 */
 	return 0;
 }

 };

-#define RAVB_PM_OPS (&ravb_dev_pm_ops)
-#else
-#define RAVB_PM_OPS NULL
-#endif
-
 static struct platform_driver ravb_driver = {
 	.probe		= ravb_probe,
 	.driver = {
 		.name	= "ravb",
-		.pm	= RAVB_PM_OPS,
+		.pm	= &ravb_dev_pm_ops,
 		.of_match_table = ravb_match_table,
 	},


